-- Daily challenges for 2026-11-19: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-11-19. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('respecting-other-peoples-time', 'Respecting Other People''s Time', 'For anyone who wants to be someone others can count on. Each day is one small way to be on time, keep messages and meetings short, answer when you said you would and give people back a little of their day.', 'Relationships', 365, array['Relationships', 'Habits', 'Values']::text[], 1, '2026-11-19T17:00:00+00:00'::timestamptz),
  ('making-friends-with-boredom', 'Making Friends with Boredom', 'For anyone who reaches for a screen the moment things get quiet. Each day is one small way to sit with a dull moment, let your mind wander and find the ideas and calm that boredom can hold.', 'Mindfulness', 365, array['Mindfulness', 'Self-Care']::text[], 1, '2026-11-19T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('respecting-other-peoples-time', 'making-friends-with-boredom');

