  ('respecting-other-peoples-time', 243, 'Cut a meeting in half by sending the background reading ahead of time.'),
  ('respecting-other-peoples-time', 244, 'Thank someone who kept a promise to you, and tell them how much it helped.'),
  ('respecting-other-peoples-time', 245, 'Put an item back where you found it in a store or library so staff need not reshelve it.'),
  ('respecting-other-peoples-time', 246, 'Learn how long the walk from the parking lot to the front door takes at a place you visit often.'),
  ('respecting-other-peoples-time', 247, 'Include the day of the week next to any date you write in a plan, so no one has to check a calendar.'),
