  ('respecting-other-peoples-time', 274, 'Help a friend with the small errand you offered, at the hour that suits them.'),
  ('respecting-other-peoples-time', 275, 'Take your coat and belongings with you as you leave a movie so the cleaning staff finish sooner.'),
  ('respecting-other-peoples-time', 276, 'Book your next appointment at an hour you can reach without rushing, even if it is not the first slot offered.'),
  ('respecting-other-peoples-time', 277, 'Keep your out of office message short, with your return date and who to contact instead.'),
  ('respecting-other-peoples-time', 278, 'Return a missed call with a short text first, asking what time suits them.'),
  ('respecting-other-peoples-time', 279, 'Take the trash or recycling out on the evening you said it was your turn.'),
  ('respecting-other-peoples-time', 280, 'Choose a gentle time like midmorning to send a personal message to someone who works nights.'),
